INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c5fe5874-1870-50de-b243-5e6ba17390cb'::uuid, '6385367e-700b-59dc-9c32-2174970e0b79'::uuid, 'Gants Nitrile Anticoupure de protection', 'Gants Nitrile Anti coupure de sécurité robuste concus pour offrire une excellente protection contre coupure.', 'Site tools', NULL, NULL, 5.0, 'MAD', 'm²', '500 Pièce', 'https://lechantier.ma/uploads/media/4a9b632a65c1.webp', $j$["https://lechantier.ma/uploads/media/4a9b632a65c1.webp", "https://lechantier.ma/uploads/media/31635d761416.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/outils-de-chantier/gants-nitrile-anticoupure-de-protection", "category_fr": "Matériel de chantier", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Gants de sécurité robustes conçus pour offrir une excellente protection contre les coupures, l’abrasion et les environnements difficiles. Fabriqués en tissu technique anticoupure avec une paume enduite de nitrile, ils assurent confort, durabilité et précision dans les travaux exigeants.\n• Haute résistance aux coupures et à l’abrasion\n• Paume nitrile anti-glisse – excellente prise même en milieu huileux\n• Respirabilité et confort grâce au tissu aéré\n• Grande flexibilité pour les travaux de précision\n• Tailles disponibles : Standard\n• Conforme aux normes EN388 EN420 EN421 CM CE (protection mécanique)Conditionnement :📦 1 sachet = 12 paires🧱 1 colis = 80 sachets (soit 960 paires)Applications : Industrie, logistique, métallurgie, maintenance, BTP…Stock disponible : Oui – livraison immédiate possiblePrix : Sur demande – tarif dégressif selon quantité.", "technical_specifications_original": "• Gants de sécurité robustes conçus pour offrir une excellente protection contre les coupures, l’abrasion et les environnements difficiles. Fabriqués en tissu technique anticoupure avec une paume enduite de nitrile, ils assurent confort, durabilité et précision dans les travaux exigeants.\n• Haute résistance aux coupures et à l’abrasion\n• Paume nitrile anti-glisse – excellente prise même en milieu huileux\n• Respirabilité et confort grâce au tissu aéré\n• Grande flexibilité pour les travaux de précision\n• Tailles disponibles : Standard\n• Conforme aux normes EN388 EN420 EN421 CM CE (protection mécanique)Conditionnement :📦 1 sachet = 12 paires🧱 1 colis = 80 sachets (soit 960 paires)Applications : Industrie, logistique, métallurgie, maintenance, BTP…Stock disponible : Oui – livraison immédiate possiblePrix : Sur demande – tarif dégressif selon quantité.", "specs": "• Gants de sécurité robustes conçus pour offrir une excellente protection contre les coupures, l’abrasion et les environnements difficiles. Fabriqués en tissu technique anticoupure avec une paume enduite de nitrile, ils assurent confort, durabilité et précision dans les travaux exigeants.\n• Haute résistance aux coupures et à l’abrasion\n• Paume nitrile anti-glisse – excellente prise même en milieu huileux\n• Respirabilité et confort grâce au tissu aéré\n• Grande flexibilité pour les travaux de précision\n• Tailles disponibles : Standard\n• Conforme aux normes EN388 EN420 EN421 CM CE (protection mécanique)Conditionnement :📦 1 sachet = 12 paires🧱 1 colis = 80 sachets (soit 960 paires)Applications : Industrie, logistique, métallurgie, maintenance, BTP…Stock disponible : Oui – livraison immédiate possiblePrix : Sur demande – tarif dégressif selon quantité."}$j$::jsonb, 'https://lechantier.ma/en/produits/outils-de-chantier/gants-nitrile-anticoupure-de-protection') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDE