INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('68d6b65d-52f2-573e-9989-e7bc0c938b00'::uuid, '34ca4eb1-299b-5ec1-8011-bd4d994972f8'::uuid, 'Perceuses-visseuses BOSCH', 'Facilite les travaux difficiles : la perceuse-visseuse à percussion sans-fil 18 V polyvalente avec double batterie Sans-fil pour un maximum de liberté, de confort et de sécurité', 'Site tools', NULL, NULL, 1550.0, 'MAD', 'Lot', '1 Lot', 'https://lechantier.ma/uploads/media/6348e07e09ef.webp', $j$["https://lechantier.ma/uploads/media/6348e07e09ef.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/outils-de-chantier/perceuses-visseuses-bosch", "category_fr": "Matériel de chantier", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Sound pressure level86,0 dB(A)Régime à vide, vitesse 2, à partir de0,0 t/minPrésélections de couple20,0Régime à vide, vitesse 2, jusqu’à1 650,0 t/minSound power level94,0 dB(A)Valeurs totales des vibrations1,5001,0Perçage dans le métalPerçage à percussion dans la maçonnerie12,800VissageTension de la batterie18,0 VPalage de serrage du mandrin, min.1,500 mmUncertainty K5,0 dBCouple (vissage en force)56,0 NmVersion longue, partie 1 (BE)Avec son moteur de 18 V, la GSB 183-LI Professional Bosch permet de disposer à tout moment et en tous lieux de la puissance nécessaire. Cet outil électroportatif sans-fil hautement polyvalent est conçu non seulement pour visser dans le bois mais aussi pour percer dans la maçonnerie et le métal. Très performant, il dispose de plusieurs fonctions destinées à prévenir les surchauffes et surcharges pour augmenter la durée de vie de la batterie et réduire les besoins de réparation. La GSB 183-LI Professional est compatible avec toutes les batteries et tous les chargeurs 18 V de Bosch Professional pour une efficience maximale et une réduction des coûts.Régime à vide, vitesse 1, jusqu’à440,0 t/minCouple maxi60,0 NmChuck capacity, min./max.1.5 / 13 mmCouple (tendre/dur/maxi)21/56/60 NmPositions de présélection de couple (nombre)20,0Plage de serrage du mandrin, max.13,0 mmPoids (sans batterie)1,200 kgNoise levelLe niveau sonore pondéré A de l'outil électroportatif est typiquement de : niveau de pression acoustique 86 dB(A) ; niveau de puissance acoustique 94 dB(A). Incertitude K = 5 dB.Positioning (Headline emotional) (BE)Power wherever you want it: 18V cordless impact drill driverRégime à vide, vitesse 1, à partir de0,0 t/minCouple (vissage en douceur)21,0 NmVersion longue, partie 2 (BE)Puissante et polyvalente, la perceuse-visseuse Bosch GSB 183-LI Professional est conçue pour effectuer des vissages jusqu’à 10 mm de diamètre dans le bois, des perçages sans percussion jusqu’à 35 mm de diamètre dans le bois et des perçages avec percussion jusqu’à 10 mm de diamètre dans la maçonnerie et le métal. Facile à utiliser, elle est idéale pour les professionnels.No-load speed (1st gear / 2nd gear)0 – 440 / 0 – 1,650 t/minNet Weight1,540 kgGross Weight3,230 kg", "technical_specifications_original": "• Sound pressure level86,0 dB(A)Régime à vide, vitesse 2, à partir de0,0 t/minPrésélections de couple20,0Régime à vide, vitesse 2, jusqu’à1 650,0 t/minSound power level94,0 dB(A)Valeurs totales des vibrations1,5001,0Perçage dans le métalPerçage à percussion dans la maçonnerie12,800VissageTension de la batterie18,0 VPalage de serrage du mandrin, min.1,500 mmUncertainty K5,0 dBCouple (vissage en force)56,0 NmVersion longue, partie 1 (BE)Avec son moteur de 18 V, la GSB 183-LI Professional Bosch permet de disposer à tout moment et en tous lieux de la puissance nécessaire. Cet outil électroportatif sans-fil hautement polyvalent est conçu non seulement pour visser dans le bois mais aussi pour percer dans la maçonnerie et le métal. Très performant, il dispose de plusieurs fonctions destinées à prévenir les surchau