INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('953b0972-db7a-515c-aeab-f4a7edfb0f52'::uuid, '91964dd3-bafc-5a0a-b8bf-cbbf65354340'::uuid, 'Panneaux Composites Aluminium/ Alucobond', 'Les panneaux composites aluminium (Alucobond) au Maroc allient légèreté, rigidité et design moderne, idéals pour façades, signalétique et décoration contemporaine.', 'Wall panels', NULL, NULL, 190.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/a3d7e9d9f29d.webp', $j$["https://lechantier.ma/uploads/media/a3d7e9d9f29d.webp", "https://lechantier.ma/uploads/media/e352d10e66e1.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/panneaux-mural/panneaux-composites-aluminium-alucobond", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Panneaux Composites Aluminium (ACP/Alucobond) – MarocLes panneaux composites aluminium, connus sous le nom Alucobond, sont constitués de deux feuilles d’aluminium thermocollées à un noyau en polyéthylène haute densité (HDPE) ou ignifuge (FR). Ils allient légèreté, rigidité, durabilité et design moderne, idéals pour les façades ventilées, la signalétique et la décoration contemporaine partout au Maroc (Casablanca, Rabat, Fès, Tanger, Marrakech, Agadir…).Pourquoi choisir l’Alucobond au Maroc ?Résistance aux UV et aux intempériesInstallation rapide et flexibleExcellente performance thermique et acoustiqueLarge choix de coloris et finitionsLongévité et garantie jusqu’à 15 ans (revêtement PVDF Kynar 500)Caractéristiques techniques principalesÉpaisseur totale : 4 mmFeuilles aluminium : 0,30 mm (alliage A-1100)Dimensions : 1,25 m ou 1,50 m (largeur) – 3,20 m ou 4,20 m (longueur)Poids spécifique : 5,3 kg/m²Isolation acoustique : 29 dBPlage de température : -50 °C à +80 °CClassement feu : ASTM E84", "technical_specifications_original": "• Panneaux Composites Aluminium (ACP/Alucobond) – MarocLes panneaux composites aluminium, connus sous le nom Alucobond, sont constitués de deux feuilles d’aluminium thermocollées à un noyau en polyéthylène haute densité (HDPE) ou ignifuge (FR). Ils allient légèreté, rigidité, durabilité et design moderne, idéals pour les façades ventilées, la signalétique et la décoration contemporaine partout au Maroc (Casablanca, Rabat, Fès, Tanger, Marrakech, Agadir…).Pourquoi choisir l’Alucobond au Maroc ?Résistance aux UV et aux intempériesInstallation rapide et flexibleExcellente performance thermique et acoustiqueLarge choix de coloris et finitionsLongévité et garantie jusqu’à 15 ans (revêtement PVDF Kynar 500)Caractéristiques techniques principalesÉpaisseur totale : 4 mmFeuilles aluminium : 0,30 mm (alliage A-1100)Dimensions : 1,25 m ou 1,50 m (largeur) – 3,20 m ou 4,20 m (longueur)Poids spécifique : 5,3 kg/m²Isolation acoustique : 29 dBPlage de température : -50 °C à +80 °CClassement feu : ASTM E84", "specs": "• Panneaux Composites Aluminium (ACP/Alucobond) – MarocLes panneaux composites aluminium, connus sous le nom Alucobond, sont constitués de deux feuilles d’aluminium thermocollées à un noyau en polyéthylène haute densité (HDPE) ou ignifuge (FR). Ils allient légèreté, rigidité, durabilité et design moderne, idéals pour les façades ventilées, la signalétique et la décoration contemporaine partout au Maroc (Casablanca, Rabat, Fès, Tanger, Marrakech, Agadir…).Pourquoi choisir l’Alucobond au Maroc ?Résistance aux UV et aux intempériesInstallation rapide et flexibleExcellente performance thermique et acoustiqueLarge choix de coloris et finitionsLongévité et garantie jusqu’à 15 ans (revêtement PVDF Kynar 500)Caractéristiques techniques principalesÉpaisseur totale : 4 mmFeuilles aluminium : 0,30 mm (alliage A-1100)Dimensions : 1,25 m ou 1,50 m (largeur) – 3,20 m ou 4,20 m (longueur)Poids spécifique : 5,3 kg/m²Isolation acoustique : 29 dBPlage de température : -50 °C à +80 °CClassement feu : ASTM E84"}$j$::jsonb, 'https://lechantier.ma/en/produits/panneaux-mural/panneaux-composites-aluminium-alucobond') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('b2518a94-b785-5df5-a0ae-a62d4bc1b846'::uuid, '88b60f9d-2dc9-592f-af67-917433f03bc7'::uuid, 'Panneaux Décoratifs PVC', 'La touche chic et pratique de vos intérieurs.', 'Wall panels', NULL, NULL, 480.0, 'MAD', 'm²', '10 Pièce', 'https://lechantier.ma/uploads/media/3770d1860dfa.webp', $j$["https://lechantier.ma/uploads/media/3770d1860dfa.webp", "https://lechantier.ma/uploads/media/bc6943a3ae89.webp", "https://lechantier.ma/uploads/media/b4950dbfbe96.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/panneaux-mural/panneaux-decoratifs-pvc", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Esthétiques – Résistants – ÉcologiquesTransformez vos murs avec une solution moderne, durable et simple à installer.🔧 Caractéristiques principales :✔️ Matériau : PVC haute densité, écologique et sans formaldéhyde ✔️ Finitions premium :\n• Marbre blanc, gris, noir\n• Pierre naturelle, doré, etc.💧 Résistants à l’eau, à l’humidité et aux insectes 🔥 Ignifugés – Classés B1 pour une sécurité accrue 🔇 Isolation thermique et acoustique performante 🧽 Surface lavable – Aucun besoin de peinture 🧰 Installation facile : collage ou clips ⏳ Durée de vie : jusqu’à 20 ans", "technical_specifications_original": "• Esthétiques – Résistants – ÉcologiquesTransformez vos murs avec une solution moderne, durable et simple à installer.🔧 Caractéristiques principales :✔️ Matériau : PVC haute densité, écologique et sans formaldéhyde ✔️ Finitions premium :\n• Marbre blanc, gris, noir\n• Pierre naturelle, doré, etc.💧 Résistants à l’eau, à l’humidité et aux insectes 🔥 Ignifugés – Classés B1 pour une sécurité accrue 🔇 Isolation thermique et acoustique performante 🧽 Surface lavable – Aucun besoin de peinture 🧰 Installation facile : collage ou clips ⏳ Durée de vie : jusqu’à 20 ans", "specs": "• Esthétiques – Résistants – ÉcologiquesTransformez vos murs avec une solution moderne, durable et simple à installer.🔧 Caractéristiques principales :✔️ Matériau : PVC haute densité, écologique et sans formaldéhyde ✔️ Finitions premium :\n• Marbre blanc, gris, noir\n• Pierre naturelle, doré, etc.💧 Résistants à l’eau, à l’humidité et aux insectes 🔥 Ignifugés – Classés B1 pour une sécurité accrue 🔇 Isolation thermique et acoustique performante 🧽 Surface lavable – Aucun besoin de peinture 🧰 Installation facile : collage ou clips ⏳ Durée de vie : jusqu’à 20 ans"}$j$::jsonb, 'https://lechantier.ma/en/produits/panneaux-mural/panneaux-decoratifs-pvc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
