INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('fe86ef05-5637-599b-a699-6819fd125b02'::uuid, '19f3ccf7-864c-535e-bb4b-7dc98dece0ca'::uuid, 'parquet', 'Le parquet stratifié est composé de plusieurs couches superposées, chacune ayant une fonction spécifique.', 'Parquet', NULL, NULL, 130.0, 'MAD', 'm²', '1 Mètre', 'https://lechantier.ma/uploads/media/fa62f9aaa613.webp', $j$["https://lechantier.ma/uploads/media/fa62f9aaa613.webp"]$j$::jsonb, $j$["Kénitra"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/parquet/parquet", "category_fr": "Parquet", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Classe d'usage :AC3 / Classe 31 : Usage domestique modéré.AC4 / Classe 32 : Usage domestique intensif ou commercial modéré.AC5 / Classe 33 : Usage commercial intensif.Résistance à l'humidité : Certains parquets stratifiés sont traités pour résister à l'eau, grâce à des technologies comme AquaSafe, permettant une utilisation dans des pièces humides. Compatibilité avec le chauffage au sol : De nombreux modèles sont compatibles, à condition de respecter les recommandations du fabricant.Systèmes de pose : La plupart des parquets stratifiés utilisent des systèmes de clipsage (pose flottante), facilitant l'installation sans colle ni clous.", "technical_specifications_original": "• Classe d'usage :AC3 / Classe 31 : Usage domestique modéré.AC4 / Classe 32 : Usage domestique intensif ou commercial modéré.AC5 / Classe 33 : Usage commercial intensif.Résistance à l'humidité : Certains parquets stratifiés sont traités pour résister à l'eau, grâce à des technologies comme AquaSafe, permettant une utilisation dans des pièces humides. Compatibilité avec le chauffage au sol : De nombreux modèles sont compatibles, à condition de respecter les recommandations du fabricant.Systèmes de pose : La plupart des parquets stratifiés utilisent des systèmes de clipsage (pose flottante), facilitant l'installation sans colle ni clous.", "specs": "• Classe d'usage :AC3 / Classe 31 : Usage domestique modéré.AC4 / Classe 32 : Usage domestique intensif ou commercial modéré.AC5 / Classe 33 : Usage commercial intensif.Résistance à l'humidité : Certains parquets stratifiés sont traités pour résister à l'eau, grâce à des technologies comme AquaSafe, permettant une utilisation dans des pièces humides. Compatibilité avec le chauffage au sol : De nombreux modèles sont compatibles, à condition de respecter les recommandations du fabricant.Systèmes de pose : La plupart des parquets stratifiés utilisent des systèmes de clipsage (pose flottante), facilitant l'installation sans colle ni clous."}$j$::jsonb, 'https://lechantier.ma/en/produits/parquet/parquet') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
