INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('81c7b7bd-4d19-5369-99ea-ffa94429c97e'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'imprimation à base d''eau galvanisé , PVC', 'imprimation à base d''eau pour, galvanisé , PVC , Aluminium , Bois , Acier lavable 750ml', 'Other', NULL, NULL, 100.0, 'MAD', 'Litre', '25kg', 'https://lechantier.ma/uploads/media/6d8e1d720e06.webp', $j$["https://lechantier.ma/uploads/media/6d8e1d720e06.webp", "https://lechantier.ma/uploads/media/65f11e943d70.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/peinture-autres/imprimation-a-base-d-eau-galvanise-pvc", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Description du produit Grand pouvoir anticorrosion, séchage rapide et excellente adhérence sur de nombreux supports : telle est cette impression phosphatante. Impression synthétique à base d’eau, dotée d’un fort pouvoir anticorrosion, d’un séchage et d’un durcissement rapides, avec une excellente adhérence sur une grande variété de supports. Elle peut être recouverte par des émaux synthétiques à base d’eau ou à base de solvant. Applications En tant qu’impression pour la protection temporaire des surfaces en fer, acier et bois exposées à l’extérieur pendant une certaine période. En tant que couche primaire pour des éléments métalliques de différentes natures tels que acier, aluminium, acier galvanisé, ainsi que bois, PVC, etc. Mode d’emploi Agiter avant utilisation. Remuer énergiquement jusqu’à obtenir un mélange parfaitement homogène. Produit prêt à l’emploi. Application possible au pinceau, au rouleau ou au pistolet. Fiche produit / Présentation Impression phosphatant anticorrosion à base d’eau, idéale pour la protection et la préparation de multiples supports.Marque : EUROTEX", "technical_specifications_original": "• Description du produit Grand pouvoir anticorrosion, séchage rapide et excellente adhérence sur de nombreux supports : telle est cette impression phosphatante. Impression synthétique à base d’eau, dotée d’un fort pouvoir anticorrosion, d’un séchage et d’un durcissement rapides, avec une excellente adhérence sur une grande variété de supports. Elle peut être recouverte par des émaux synthétiques à base d’eau ou à base de solvant. Applications En tant qu’impression pour la protection temporaire des surfaces en fer, acier et bois exposées à l’extérieur pendant une certaine période. En tant que couche primaire pour des éléments métalliques de différentes natures tels que acier, aluminium, acier galvanisé, ainsi que bois, PVC, etc. Mode d’emploi Agiter avant utilisation. Remuer énergiquement jusqu’à obtenir un mélange parfaitement homogène. Produit prêt à l’emploi. Application possible au pinceau, au rouleau ou au pistolet. Fiche produit / Présentation Impression phosphatant anticorrosion à base d’eau, idéale pour la protection et la préparation de multiples supports.Marque : EUROTEX", "specs": "• Description du produit Grand pouvoir anticorrosion, séchage rapide et excellente adhérence sur de nombreux supports : telle est cette impression phosphatante. Impression synthétique à base d’eau, dotée d’un fort pouvoir anticorrosion, d’un séchage et d’un durcissement rapides, avec une excellente adhérence sur une grande variété de supports. Elle peut être recouverte par des émaux synthétiques à base d’eau ou à base de solvant. Applications En tant qu’impression pour la protection temporaire des surfaces en fer, acier et bois exposées à l’extérieur pendant une certaine période. En tant que couche primaire pour des éléments métalliques de différentes natures tels que acier, aluminium, acier galvanisé, ainsi que bois, PVC, etc. Mode d’emploi Agiter avant utilisation. Remuer énergiquement jusqu’à obtenir un mélange parfaitement homogène. Produit prêt à l’emploi. Application possible au pinceau, au rouleau ou au pistolet. Fiche produit / Présentation Impression phosphatant anticorrosion à base d’eau, idéale pour la protection et la préparation de multiples supports.Marque : EUROTEX"}$j$::jsonb, 'https://lechantier.ma/en/produits/peinture-autres/imprimation-a-base-d-eau-galvanise-pvc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0c7b0c9c-23d3-5bd2-a3b7-42f644f8d11f'::uuid, '9056c079-eaf5-5665-ab5d-ae5958ddadd3'::uuid, 'Jawda 7000 1ere Choix Peinture Vinylique', 'Jawda 7000 – Peinture professionnelle intérieure / extérieure 1ere Choix Jawda 7000 est une peinture acrylique haut de gamme conçue pour les façades. 5Kg / 10Kg / 29Kg / 45 Kg', 'Other', NULL, NULL, 150.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/bc981d1e0f27.webp', $j$["https://lechantier.ma/uploads/media/bc981d1e0f27.webp", "https://lechantier.ma/uploads/media/556302fbdc62.webp", "https://lechantier.ma/uploads/media/4d264443af75.webp", "https://lechantier.ma/uploads/media/afbd03d86075.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/peinture-autres/jawda-7000-1ere-choix-peinture-vinylique", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Jawda 7000 est une peinture de haute qualité spécialement conçue pour offrir une excellente résistance aux conditions climatiques difficiles. Elle est idéale pour les façades extérieures grâce à sa formulation riche et durable.Caractéristiques principales :Très bonne adhérence sur supports neufs ou anciens.Haute résistance aux UV, à l’humidité et aux intempéries.Finition mate ou satinée (selon version).Facile à appliquer au rouleau, pinceau ou pistolet.Rendement : environ 8 à 10 m²/L selon le support.Domaine d'application :Façades en béton, ciment, enduit ou surfaces préparées.", "technical_specifications_original": "• Jawda 7000 est une peinture de haute qualité spécialement conçue pour offrir une excellente résistance aux conditions climatiques difficiles. Elle est idéale pour les façades extérieures grâce à sa formulation riche et durable.Caractéristiques principales :Très bonne adhérence sur supports neufs ou anciens.Haute résistance aux UV, à l’humidité et aux intempéries.Finition mate ou satinée (selon version).Facile à appliquer au rouleau, pinceau ou pistolet.Rendement : environ 8 à 10 m²/L selon le support.Domaine d'application :Façades en béton, ciment, enduit ou surfaces préparées.", "specs": "• Jawda 7000 est une peinture de haute qualité spécialement conçue pour offrir une excellente résistance aux conditions climatiques difficiles. Elle est idéale pour les façades extérieures grâce à sa formulation riche et durable.Caractéristiques principales :Très bonne adhérence sur supports neufs ou anciens.Haute résistance aux UV, à l’humidité et aux intempéries.Finition mate ou satinée (selon version).Facile à appliquer au rouleau, pinceau ou pistolet.Rendement : environ 8 à 10 m²/L selon le support.Domaine d'application :Façades en béton, ciment, enduit ou surfaces préparées."}$j$::jsonb, 'https://lechantier.ma/en/produits/peinture-autres/jawda-7000-1ere-choix-peinture-vinylique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('8d3252e2-a53a-55ab-ac94-5c629777e5ab'::uuid, '7d322a35-dcf1-5dfd-9b6f-55d25b5f1824'::uuid, 'OPTICOLLE 2500 20 KGS', 'Idéale pour l''assemblage et le placage en intérieur de tous types de bois et leurs dérivés : Bois tendres, durs, exotiques, agglomérés, contreplaqués, lamifiés, stratifiés.', 'Other', NULL, NULL, 330.0, 'MAD', 'Pièce', '20 Pièce', 'https://lechantier.ma/uploads/media/67190641e4f4.webp', $j$["https://lechantier.ma/uploads/media/67190641e4f4.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/peinture-autres/opticolle-2500-20-kgs", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Viscosité à 20° C brookflield axe 6 RPM 50 : 5000 – 7000 cpsTeneur en extrait sec : 25% + ou -1Indice d’acide : 1 – 1.4 pH : 4 – 5Densité : 1.08Non inflammable à l’emploiInvisible après séchage", "technical_specifications_original": "• Viscosité à 20° C brookflield axe 6 RPM 50 : 5000 – 7000 cpsTeneur en extrait sec : 25% + ou -1Indice d’acide : 1 – 1.4 pH : 4 – 5Densité : 1.08Non inflammable à l’emploiInvisible après séchage", "specs": "• Viscosité à 20° C brookflield axe 6 RPM 50 : 5000 – 7000 cpsTeneur en extrait sec : 25% + ou -1Indice d’acide : 1 – 1.4 pH : 4 – 5Densité : 1.08Non inflammable à l’emploiInvisible après séchage"}$j$::jsonb, 'https://lechantier.ma/en/produits/peinture-autres/opticolle-2500-20-kgs') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('98db6549-f339-544e-851d-8eb6b6556536'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Peinture Igniflamex 25kg blanc', 'Peinture intumescente à base d''eau conçue pour offrir une protection passive contre l''incendie', 'Other', NULL, NULL, 3500.0, 'MAD', 'Kilogramme', '25 Kilogramme', 'https://lechantier.ma/uploads/media/1e7d2b5ad76a.webp', $j$["https://lechantier.ma/uploads/media/1e7d2b5ad76a.webp", "https://lechantier.ma/uploads/media/875e82b30437.webp", "https://lechantier.ma/uploads/media/f3d9dd0ebc05.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/peinture-autres/peinture-igniflamex-25kg-blanc", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Peinture intumescente à base d’eau conçue pour offrir une protection passive contre l’incendie. En cas d’exposition à de hautes températures, cette peinture réagit en formant une mousse isolante épaisse et stable, qui retarde significativement la propagation des flammes et protège les éléments structurels (acier, béton, bois) contre la dégradation thermique. Caractéristiques techniques : Type : Peinture intumescente à base d’eau Aspect : Finition mate blanche Rendement théorique : Environ 1 m² / litre Application : Brosse, rouleau ou pistolet airless Utilisation : Intérieur et extérieur (avec finition adaptée) Données techniques de cette peinture intumescente antifeu pour structures métalliques Couleur : Blanc Finition : Mate % de solides : 71 ± 2 % COV : Sans COV, conforme à la directive européenne sur les émissions de solvants (SED) 1999/13/CE Épaisseur recommandée : 350 – 550 microns secs par couche, selon la méthode d’application Méthodes d’application : Pistolet AIRLESS, brosse ou rouleau pH : 8,0 ± 1 Point d’inflammation : > 100 °C Densité : 1,37 ± 0,03 Recouvrable : après 24 heures à 20 °C et 60 % d’humidité relative Diluant : Eau (uniquement pour le nettoyage) Résistance au feu : R-15’, R-30’, R-60’ et R-90’ sur poutres et poteaux ouverts R-30’ sur poutres fermées", "technical_specifications_original": "• Peinture intumescente à base d’eau conçue pour offrir une protection passive contre l’incendie. En cas d’exposition à de hautes températures, cette peinture réagit en formant une mousse isolante épaisse et stable, qui retarde significativement la propagation des flammes et protège les éléments structurels (acier, béton, bois) contre la dégradation thermique. Caractéristiques techniques : Type : Peinture intumescente à base d’eau Aspect : Finition mate blanche Rendement théorique : Environ 1 m² / litre Application : Brosse, rouleau ou pistolet airless Utilisation : Intérieur et extérieur (avec finition adaptée) Données techniques de cette peinture intumescente antifeu pour structures métalliques Couleur : Blanc Finition : Mate % de solides : 71 ± 2 % COV : Sans COV, conforme à la directive européenne sur les émissions de solvants (SED) 1999/13/CE Épaisseur recommandée : 350 – 550 microns secs par couche, selon la méthode d’application Méthodes d’application : Pistolet AIRLESS, brosse ou rouleau pH : 8,0 ± 1 Point d’inflammation : > 100 °C Densité : 1,37 ± 0,03 Recouvrable : après 24 heures à 20 °C et 60 % d’humidité relative Diluant : Eau (uniquement pour le nettoyage) Résistance au feu : R-15’, R-30’, R-60’ et R-90’ sur poutres et poteaux ouverts R-30’ sur poutres fermées", "specs": "• Peinture intumescente à base d’eau conçue pour offrir une protection passive contre l’incendie. En cas d’exposition à de hautes températures, cette peinture réagit en formant une mousse isolante épaisse et stable, qui retarde significativement la propagation des flammes et protège les éléments structurels (acier, béton, bois) contre la dégradation thermique. Caractéristiques techniques : Type : Peinture intumescente à base d’eau Aspect : Finition mate blanche Rendement théorique : Environ 1 m² / litre Application : Brosse, rouleau ou pistolet airless Utilisation : Intérieur et extérieur (avec finition adaptée) Données techniques de cette peinture intumescente antifeu pour structures métalliques Couleur : Blanc Finition : Mate % de solides : 71 ± 2 % COV : Sans COV, conforme à la directive européenne sur les émissions de solvants (SED) 1999/13/CE Épaisseur recommandée : 350 – 550 microns secs par couche, selon la méthode d’application Méthodes d’application : Pistolet AIRLESS, brosse ou rouleau pH : 8,0 ± 1 Point d’inflammation : > 100 °C Densité : 1,37 ± 0,03 Recouvrable : après 24 heures à 20 °C et 60 % d’humidité relative Diluant : Eau (uniquement pour le nettoyage) Résistance au feu : R-15’, R-30’, R-60’ et R-90’ sur poutres et poteaux ouverts R-30’ sur poutres fermées"}$j$::jsonb, 'https://lechantier.ma/en/produits/peinture-autres/peinture-igniflamex-25kg-blanc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
