INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('78bc610c-3878-51d1-9eb9-d838cacbb7dd'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Impertex', 'DESCRIPTION DU PRODUIT IMPERTEX WATERPROOF est un revêtement à base d''eau pour l''étanchéité professionnelle des terrasses et des façades.', 'Paint', 'Autres', NULL, 990.0, 'MAD', 'Kilogramme', '1 Kilogramme', 'https://lechantier.ma/uploads/media/e2cbe6e00dd6.webp', $j$["https://lechantier.ma/uploads/media/e2cbe6e00dd6.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/peinture/impertex", "category_fr": "Peinture", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Ce produit offre une étanchéité totale et une protection complète contre l'eau et l'humidité. Hydrofuge, résistant aux UV et à la pluie, il prévient l'humidité et les fuites. Il présente une finition satinée d'aspect professionnel, une grande durabilité, une flexibilité optimale et une excellente adhérence aux surfaces horizontales et verticales.", "technical_specifications_original": "• Ce produit offre une étanchéité totale et une protection complète contre l'eau et l'humidité. Hydrofuge, résistant aux UV et à la pluie, il prévient l'humidité et les fuites. Il présente une finition satinée d'aspect professionnel, une grande durabilité, une flexibilité optimale et une excellente adhérence aux surfaces horizontales et verticales.", "specs": "• Ce produit offre une étanchéité totale et une protection complète contre l'eau et l'humidité. Hydrofuge, résistant aux UV et à la pluie, il prévient l'humidité et les fuites. Il présente une finition satinée d'aspect professionnel, une grande durabilité, une flexibilité optimale et une excellente adhérence aux surfaces horizontales et verticales."}$j$::jsonb, 'https://lechantier.ma/en/produits/peinture/impertex') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('b70e9d89-7f47-5442-9a57-96241240cd0b'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Membrane liquide de polyuréthane |', 'Membrane liquide à composant unique pour l''étanchéité impermeabilizacióndede différents types de surfaces: béton, mortier, fibrocement, produits bitumineux, acier, salles de bains, cuisines, chaussées piétonnes, stands ou réservoirs d''eau. Il a le marquage CE (voir toute la documentation ci-dessous, sous "Jetons de produits") Rendement : 2 kg/m 2 (1,5 L) au total Produit auto-nivelant et facile à utiliser', 'Paint', 'Revêtement extérieur', NULL, 4000.0, 'MAD', 'Litre', '500 m²', 'https://lechantier.ma/uploads/media/38741bc7e17a.webp', $j$["https://lechantier.ma/uploads/media/38741bc7e17a.webp", "https://lechantier.ma/uploads/media/dfe68cd3535f.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/peinture/membrane-liquide-de-polyurethane", "category_fr": "Peinture", "supplier_matching_status": "matched", "technical_specifications_detailed": "• une solution d’étanchéité flexible, durable et polyvalente pour protéger les surfaces contre l’eau et les intempéries.", "technical_specifications_original": "• une solution d’étanchéité flexible, durable et polyvalente pour protéger les surfaces contre l’eau et les intempéries.", "specs": "• une solution d’étanchéité flexible, durable et polyvalente pour protéger les surfaces contre l’eau et les intempéries."}$j$::jsonb, 'https://lechantier.ma/en/produits/peinture/membrane-liquide-de-polyurethane') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity 