INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c6bd1e09-5bbd-563f-a836-2f9039589ee6'::uuid, '4df5d382-c243-5ed5-b639-46aaf17e76b6'::uuid, 'Marbre Black Mars pour sols, cuisines...', 'Le marbre Black Mars est un marbre marocain au fond noir profond, qui donne du contraste et de la profondeur à chaque surface. Une fois poli, il renvoie la lumière et agrandit visuellement la pièce. Il se coupe en carrelage, plan de cuisine, douche, marches d''escalier et parement de façade, et trouve aussi sa place au jardin. Compact et peu poreux, il supporte l''usage quotidien. Chaque dalle a son veinage propre, donc chaque pose est unique.', 'Natural stone', 'Marbre', NULL, 420.0, 'MAD', 'm²', '10 Mètre', 'https://lechantier.ma/uploads/media/50716d80fec1.webp', $j$["https://lechantier.ma/uploads/media/50716d80fec1.webp", "https://lechantier.ma/uploads/media/3172bf7ed3b6.webp", "https://lechantier.ma/uploads/media/d48fa648957c.webp", "https://lechantier.ma/uploads/media/7c3c51224688.webp", "https://lechantier.ma/uploads/media/4edbd0ca45ab.webp"]$j$::jsonb, $j$["Mohammedia"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/pierre-naturelle/marbre-black-mars-pour-sols-cuisines", "category_fr": "Pierre naturelle", "supplier_matching_status": "matched", "technical_specifications_detailed": "• MatériauMarbre naturel du MarocNom commercialBlack MarsCouleurNoir profond [préciser la présence ou non de veines blanches]Finitions disponiblesPoli, adouci, brossé, flammé [à confirmer]DimensionsDalles et carreaux, coupe sur mesure]", "technical_specifications_original": "• MatériauMarbre naturel du MarocNom commercialBlack MarsCouleurNoir profond [préciser la présence ou non de veines blanches]Finitions disponiblesPoli, adouci, brossé, flammé [à confirmer]DimensionsDalles et carreaux, coupe sur mesure]", "specs": "• MatériauMarbre naturel du MarocNom commercialBlack MarsCouleurNoir profond [préciser la présence ou non de veines blanches]Finitions disponiblesPoli, adouci, brossé, flammé [à confirmer]DimensionsDalles et carreaux, coupe sur mesure]"}$j$::jsonb, 'https://lechantier.ma/en/produits/pierre-naturelle/marbre-black-mars-pour-sols-cuisines') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('8fcfe12d-2609-5cbb-98a5-8fee99997f36'::uuid, '4df5d382-c243-5ed5-b639-46aaf17e76b6'::uuid, 'Marbre Gris Royal - The Wyndham', 'Le marbre Gris Royal Wyndham est un marbre marocain aux tons gris, parcouru d''un veinage fin et régulier qui anime la surface sans la charger. Sa teinte neutre s''accorde avec le bois, le blanc, le noir et les métaux, dans un intérieur moderne comme classique. Il se coupe en carrelage de sol, revêtement mural, plan de travail, marche d''escalier et plan de salle de bain. Dense et facile à entretenir, il se travaille en finition polie, adoucie ou brossée selon l''ambiance voulue.', 'Natural stone', 'Marbre', NULL, 120.0, 'MAD', 'm²', '10 Mètre', 'https://lechantier.ma/uploads/media/9d7770587ac0.webp', $j$["https://lechantier.ma/uploads/media/9d7770587ac0.webp", "https://lechantier.ma/uploads/media/982ca607be0a.webp", "https://lechantier.ma/uploads/media/86303fbf8268.webp", "https://lechantier.ma/uploads/media/518796d0e75c.webp", "https://lechantier.ma/uploads/media/e89cb1b1e06e.webp"]$j$::jsonb, $j$["Mohammedia"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/pierre-naturelle/marbre-gris-royal-the-wyndham", "category_fr": "Pierre naturelle", "supplier_matching_status": "matched", "technical_specifications_detailed": "• MatériauMarbre naturel du MarocOrigineRégion de Khénifra, Moyen AtlasNom commercialGris Royal - The WyndhamCouleurGris avec veinage blancParticularitéPrésence occasionnelle de fossilesFinitions disponiblesPolie, adoucie, brosséeDimensionsCarreaux et dalles, coupe sur mesure Épaisseur2 cm, 3 cm", "technical_specifications_original": "• MatériauMarbre naturel du MarocOrigineRégion de Khénifra, Moyen AtlasNom commercialGris Royal - The WyndhamCouleurGris avec veinage blancParticularitéPrésence occasionnelle de fossilesFinitions disponiblesPolie, adoucie, brosséeDimensionsCarreaux et dalles, coupe sur mesure Épaisseur2 cm, 3 cm", "specs": "• MatériauMarbre naturel du MarocOrigineRégion de Khénifra, Moyen AtlasNom commercialGris Royal - The WyndhamCouleurGris avec veinage blancParticularitéPrésence occasionnelle de fossilesFinitions disponiblesPolie, adoucie, brosséeDimensionsCarreaux et dalles, coupe sur mesure Épaisseur2 cm, 3 cm"}$j$::jsonb, 'https://lechantier.ma/en/produits/pierre-naturelle/marbre-gris-royal-the-wyndham') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
