INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('1986b1f3-add1-5698-a890-5e0005f982b7'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Patagonia marbre', 'Le marbre Patagonia est une pierre naturelle spectaculaire, reconnaissable à son fond clair parcouru de veines et de formations minérales très contrastées dans des tons de noir, gris, beige et parfois doré.', 'Natural stone', 'Quartz', NULL, 3800.0, 'MAD', 'm²', '10 Mètre', 'https://lechantier.ma/uploads/media/d977c633db15.webp', $j$["https://lechantier.ma/uploads/media/d977c633db15.webp", "https://lechantier.ma/uploads/media/1f5d2090c3cd.webp", "https://lechantier.ma/uploads/media/c618c3584e7b.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/pierre-naturelle/patagonia-marbre", "category_fr": "Pierre naturelle", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Nature : quartzite naturel, souvent commercialisé comme « Patagonia ».Composition : quartz, feldspaths et différents minéraux/inclusions.Aspect : fond blanc/crème avec des concentrations minérales noires, grises, brunes et parfois dorées.", "technical_specifications_original": "• Nature : quartzite naturel, souvent commercialisé comme « Patagonia ».Composition : quartz, feldspaths et différents minéraux/inclusions.Aspect : fond blanc/crème avec des concentrations minérales noires, grises, brunes et parfois dorées.", "specs": "• Nature : quartzite naturel, souvent commercialisé comme « Patagonia ».Composition : quartz, feldspaths et différents minéraux/inclusions.Aspect : fond blanc/crème avec des concentrations minérales noires, grises, brunes et parfois dorées."}$j$::jsonb, 'https://lechantier.ma/en/produits/pierre-naturelle/patagonia-marbre') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = E