ion[split face / bouchardé / adouci / vieilli]Dimensions[ex. 10×10x8, 8×8x10 cm, à confirmer]Épaisseur[à confirmer]UsageExtérieur : allées, terrasses, cours, abords de piscine"}$j$::jsonb, 'https://lechantier.ma/en/produits/pierre-naturelle/paving-paves-carres-cobbles-batons') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
