INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('54db58e8-cd59-50d1-ad97-1def06b6ab16'::uuid, 'd29b8efe-0bb8-5a15-ae3f-655149aacc4b'::uuid, 'chlore pouder 5kg astral pool', 'AstralPool Chlore Poudre 5kg', 'Pool', NULL, NULL, 269.0, 'MAD', 'Kilogramme', '1 Kilogramme', 'https://lechantier.ma/uploads/media/f3a666db6e87.webp', $j$["https://lechantier.ma/uploads/media/f3a666db6e87.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/piscine-piscine/chlore-pouder-5kg-astral-pool", "category_fr": "Piscine", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Offrez à votre piscine une propreté et une clarté exceptionnelles avec le chlore en poudre professionnel AstralPool. Spécialement conçu pour désinfecter efficacement l'eau, ce produit élimine les bactéries, les algues et autres contaminants, assurant une eau saine et cristalline pour des baignades en toute sérénité. Son format de 5kg est idéal pour un traitement régulier et efficace.\n• Caractéristiques :Type : Chlore poudreVolume : 5 kgMarque : AstralPoolUtilisation : Traitement et entretien régulier📦 Dosage recommandé :Traitement initial : 10g pour 1m³ d’eau.Entretien : 2-3g pour 1m³ d’eau, à ajouter quotidiennement, de préférence le soir après la baignade.Mode d'emploi : Dissoudre la quantité nécessaire dans un seau d'eau, puis répartir la solution uniformément dans la piscine, filtration en marche.⚠️ Conseils & Précautions :Conserver dans un endroit sec et à l’abri de la lumière.Porter des gants et éviter le contact direct avec la peau.Lire attentivement l’étiquette avant utilisation.🌊 Compatible avec tous types de piscines.", "technical_specifications_original": "• Offrez à votre piscine une propreté et une clarté exceptionnelles avec le chlore en poudre professionnel AstralPool. Spécialement conçu pour désinfecter efficacement l'eau, ce produit élimine les bactéries, les algues et autres contaminants, assurant une eau saine et cristalline pour des baignades en toute sérénité. Son format de 5kg est idéal pour un traitement régulier et efficace.\n• Caractéristiques :Type : Chlore poudreVolume : 5 kgMarque : AstralPoolUtilisation : Traitement et entretien régulier📦 Dosage recommandé :Traitement initial : 10g pour 1m³ d’eau.Entretien : 2-3g pour 1m³ d’eau, à ajouter quotidiennement, de préférence le soir après la baignade.Mode d'emploi : Dissoudre la quantité nécessaire dans un seau d'eau, puis répartir la solution uniformément dans la piscine, filtration en marche.⚠️ Conseils & Précautions :Conserver dans un endroit sec et à l’abri de la lumière.Porter des gants et éviter le contact direct avec la peau.Lire attentivement l’étiquette avant utilisation.🌊 Compatible avec tous types de piscines.", "specs": "• Offrez à votre piscine une propreté et une clarté exceptionnelles avec le chlore en poudre professionnel AstralPool. Spécialement conçu pour désinfecter efficacement l'eau, ce produit élimine les bactéries, les algues et autres contaminants, assurant une eau saine et cristalline pour des baignades en toute sérénité. Son format de 5kg est idéal pour un traitement régulier et efficace.\n• Caractéristiques :Type : Chlore poudreVolume : 5 kgMarque : AstralPoolUtilisation : Traitement et entretien régulier📦 Dosage recommandé :Traitement initial : 10g pour 1m³ d’eau.Entretien : 2-3g pour 1m³ d’eau, à ajouter quotidiennement, de préférence le soir après la baignade.Mode d'emploi : Dissoudre la quantité nécessaire dans un seau d'eau, puis répartir la solution uniformément dans la piscine, filtration en marche.⚠️ Conseils & Précautions :Conserver dans un endroit sec et à l’abri de la lumière.Porter des gants et éviter le contact direct avec la peau.Lire attentivement l’étiquette avant utilisation.🌊 Compatible avec tous types de piscines."}$j$::jsonb, 'https://lechantier.ma/en/produits/piscine-piscine/chlore-pouder-5kg-astral-pool') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
